import java.util.*;

abstract class Node {
  public abstract int evaluate();
}

class NumNode extends Node {
  private final int value;

  NumNode(int value) {
    this.value = value;
  }

  public int evaluate() {
    return value;
  }
}

class OpNode extends Node {
  private final char op;
  private final Node left, right;

  OpNode(char op, Node left, Node right) {
    this.op = op;
    this.left = left;
    this.right = right;
  }

  public int evaluate() {
    int a = left.evaluate(), b = right.evaluate();
    switch (op) {
      case '+':
        return a + b;
      case '-':
        return a - b;
      case '*':
        return a * b;
      default:
        return a / b;
    }
  }
}

class TreeBuilder {
  Node buildTree(String[] postfix) {
    Deque<Node> stack = new ArrayDeque<>();
    for (String t : postfix) {
      if (t.length() == 1 && "+-*/".indexOf(t.charAt(0)) >= 0) {
        Node right = stack.pop(), left = stack.pop();
        stack.push(new OpNode(t.charAt(0), left, right));
      } else stack.push(new NumNode(Integer.parseInt(t)));
    }
    return stack.pop();
  }
}
